export function SpecLinks({open,items}:{open:MobileProps['open'];items:[string,string,string,string?][]}){return <div className="pj-links">{items.map(([icon,label,kind,id='home'])=><button key={kind+id} onClick={()=>open(kind,id)}><i><MarkGlyph mark={icon}/></i><span>{label}</span><b><AppGlyph name="next" size={18}/></b></button>)}</div>}
function Intro({mark,title,children}:{mark:string;title:string;children:ReactNode}){return <div className="pj-intro">{mark&&<span><MarkGlyph mark={mark}/></span>}<h2>{title}</h2><p>{children}</p></div>}
function Note({children}:{children:ReactNode}){return <p className="pj-note">{children}</p>}
function Blank({children}:{children:ReactNode}){return <div className="xf-empty">{children}</div>}
function Section({title,children}:{title:string;children:ReactNode}){return <section className="pj-section"><h3>{title}</h3>{children}</section>}
function F({label,name,type='text',value,required=true}:{label:string;name:string;type?:string;value?:string|number;required?:boolean}){return <label className="pj-field">{label}<input name={name} type={type} defaultValue={value} required={required} maxLength={200} min={type==='number'?0:undefined}/></label>}
function Text({label,name,value,required=false}:{label:string;name:string;value?:string;required?:boolean}){return <label className="pj-field">{label}<textarea name={name} defaultValue={value} maxLength={2000} required={required}/></label>}
function Choice({label,name,options,value}:{label:string;name:string;options:string[];value?:string}){return <label className="pj-field">{label}<select name={name} defaultValue={value}>{options.map(o=><option key={o}>{o}</option>)}</select></label>}

